/* Custom styles for modern design and accessibility */
.form-field {
    @apply mb-6;
}

.radio-group-item {
    @apply flex items-center p-4 border-2 border-gray-200 rounded-lg cursor-pointer transition-all hover:bg-blue-50 hover:border-blue-200;
}

.radio-group-item:focus-within {
    @apply ring-2 ring-blue-500 border-blue-500;
}

.radio-group-item input[type="radio"]:checked + label {
    @apply font-semibold;
}

.radio-group-item input[type="radio"] {
    @apply h-5 w-5 text-blue-600 border-gray-300 focus:ring-blue-500;
}

button[type="submit"] {
    @apply w-full bg-blue-600 text-white font-bold py-3 px-6 rounded-lg shadow-lg hover:bg-blue-700 focus:outline-none focus:ring-4 focus:ring-blue-300 transition-all;
}

const { useState } = React;

const RadioButton = ({ id, name, value, label, checked, onChange }) => (
  <div className="radio-group-item">
    <input
      type="radio"
      id={id}
      name={name}
      value={value}
      checked={checked}
      onChange={onChange}
      className="mr-3"
    />
    <label htmlFor={id} className="flex-grow cursor-pointer text-lg text-gray-700">
      {label}
    </label>
  </div>
);

const NotificationForm = () => {
  const [preference, setPreference] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!preference) {
      alert('Please select a notification preference.');
      return;
    }
    alert(`You selected: ${preference}`);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      <main className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full border border-gray-100">
        <header className="mb-8">
          <h1 className="text-3xl font-extrabold text-gray-900 mb-2">Preferences</h1>
          <p className="text-gray-500">Update how you want to stay in touch.</p>
        </header>

        <form onSubmit={handleSubmit}>
          <div className="form-field">
            <fieldset>
              <legend className="text-xl font-bold text-gray-800 mb-4">
                How do you prefer to receive notifications?
              </legend>
              <div className="space-y-3">
                <RadioButton
                  id="email"
                  name="notification"
                  value="Email"
                  label="Email"
                  checked={preference === 'Email'}
                  onChange={(e) => setPreference(e.target.value)}
                />
                <RadioButton
                  id="sms"
                  name="notification"
                  value="SMS"
                  label="SMS"
                  checked={preference === 'SMS'}
                  onChange={(e) => setPreference(e.target.value)}
                />
                <RadioButton
                  id="push"
                  name="notification"
                  value="Push Notifications"
                  label="Push Notifications"
                  checked={preference === 'Push Notifications'}
                  onChange={(e) => setPreference(e.target.value)}
                />
              </div>
            </fieldset>
          </div>

          <button type="submit">
            Save Preferences
          </button>
        </form>
      </main>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<NotificationForm />);

